// Validate required incoming clinical intake fields
const items = $input.all();
const results = [];

for (const item of items) {
  // Support both body-wrapped payloads and flat payloads
  const raw = item.json.body && typeof item.json.body === 'object' ? item.json.body : item.json;

  // Resolve Name candidate
  let name = '';
  if (raw.q3_fullName && typeof raw.q3_fullName === 'object') {
    name = `${raw.q3_fullName.first || ''} ${raw.q3_fullName.last || ''}`.trim();
  } else if (typeof raw.q3_fullName === 'string') {
    name = raw.q3_fullName.trim();
  } else if (raw.patient_name) {
    name = String(raw.patient_name).trim();
  } else if (raw.patient && raw.patient.name) {
    name = String(raw.patient.name).trim();
  }

  const email = raw.q4_email || raw.patient_email || raw.email || (raw.patient && raw.patient.email) || '';
  const phone = raw.q5_phone || raw.patient_phone || raw.phone || (raw.patient && raw.patient.phone) || '';
  const dob = raw.q6_dateOfBirth || raw.date_of_birth || raw.dob || (raw.patient && raw.patient.date_of_birth) || '';
  const reason = raw.q7_reasonForVisit || raw.reason_for_visit || raw.chief_complaint || (raw.patient && raw.patient.reason_for_visit) || '';
  const symptoms = raw.q8_symptoms || raw.symptoms || (raw.patient && raw.patient.symptoms) || '';
  const submissionId = raw.submissionID || raw.submission_id || raw.intake_id || (raw.patient && raw.patient.intake_id) || '';

  const missing = [];
  if (!name) missing.push('full name (q3_fullName / patient_name)');
  if (!email) missing.push('email (q4_email / patient_email)');
  if (!phone) missing.push('phone (q5_phone / patient_phone)');
  if (!dob) missing.push('date of birth (q6_dateOfBirth / date_of_birth)');
  if (!reason) missing.push('reason for visit (q7_reasonForVisit / reason_for_visit)');
  if (!symptoms) missing.push('symptoms (q8_symptoms / symptoms)');
  if (!submissionId) missing.push('submission ID (submissionID / intake_id)');

  if (missing.length > 0) {
    throw new Error(`INVALID_INPUT: Required intake information is missing: ${missing.join(', ')}`);
  }

  results.push({
    json: {
      ...raw,
      _validated: true
    }
  });
}

return results;

// Extract and normalize patient fields from validated payload
const items = $input.all();
const results = [];

for (const item of items) {
  const raw = item.json.body && typeof item.json.body === 'object' ? item.json.body : item.json;

  // 1. Patient Name
  let patientName = '';
  if (raw.q3_fullName && typeof raw.q3_fullName === 'object') {
    patientName = `${raw.q3_fullName.first || ''} ${raw.q3_fullName.last || ''}`.trim();
  } else if (typeof raw.q3_fullName === 'string') {
    patientName = raw.q3_fullName.trim();
  } else if (raw.patient_name) {
    patientName = String(raw.patient_name).trim();
  } else if (raw.patient && raw.patient.name) {
    patientName = String(raw.patient.name).trim();
  }
  if (!patientName) patientName = 'Patient';

  // 2. Contact & Demographics
  const patientEmail = raw.q4_email || raw.patient_email || raw.email || (raw.patient && raw.patient.email) || 'patient@example.com';
  const patientPhone = raw.q5_phone || raw.patient_phone || raw.phone || (raw.patient && raw.patient.phone) || 'N/A';
  const dateOfBirth = raw.q6_dateOfBirth || raw.date_of_birth || raw.dob || (raw.patient && raw.patient.date_of_birth) || '1980-01-01';

  // 3. Clinical Symptoms & History
  const reasonForVisit = raw.q7_reasonForVisit || raw.reason_for_visit || raw.chief_complaint || (raw.patient && raw.patient.reason_for_visit) || 'Medical evaluation';
  const symptoms = raw.q8_symptoms || raw.symptoms || (raw.patient && raw.patient.symptoms) || 'No symptoms described';
  const symptomDuration = raw.q9_duration || raw.symptom_duration || raw.duration || (raw.patient && raw.patient.symptom_duration) || 'Not specified';

  let painLevel = 'N/A';
  if (raw.q10_painLevel !== undefined && raw.q10_painLevel !== null) {
    painLevel = String(raw.q10_painLevel);
  } else if (raw.pain_level !== undefined && raw.pain_level !== null) {
    painLevel = String(raw.pain_level);
  }

  const currentMedications = raw.q11_medications || raw.current_medications || raw.medications || (raw.patient && raw.patient.current_medications) || 'None';
  const allergies = raw.q12_allergies || raw.allergies || (raw.patient && raw.patient.allergies) || 'None';
  const medicalHistory = raw.q13_medicalHistory || raw.medical_history || raw.history || (raw.patient && raw.patient.medical_history) || 'None reported';
  const insuranceProvider = raw.q14_insurance || raw.insurance_provider || raw.insurance || (raw.patient && raw.patient.insurance_provider) || 'Self-pay';

  const preferredDate = raw.q15_preferredDate || raw.preferred_date || (raw.patient && raw.patient.preferred_date) || new Date().toISOString().split('T')[0];
  const preferredTime = raw.q16_preferredTime || raw.preferred_time || (raw.patient && raw.patient.preferred_time) || 'Immediate';

  const rawSubId = raw.submissionID || raw.submission_id || raw.intake_id || (raw.patient && raw.patient.intake_id) || String(Date.now());
  const intakeId = `MED-${rawSubId}-${Date.now()}`;
  const submissionDate = new Date().toISOString();

  results.push({
    json: {
      patient_name: patientName,
      patient_email: patientEmail,
      patient_phone: patientPhone,
      date_of_birth: dateOfBirth,
      reason_for_visit: reasonForVisit,
      symptoms: symptoms,
      symptom_duration: symptomDuration,
      pain_level: painLevel,
      current_medications: currentMedications,
      allergies: allergies,
      medical_history: medicalHistory,
      insurance_provider: insuranceProvider,
      preferred_date: preferredDate,
      preferred_time: preferredTime,
      intake_id: intakeId,
      submission_date: submissionDate
    }
  });
}

return results;

// Calculate patient age from date of birth with strict validation
const items = $input.all();
const results = [];

for (const item of items) {
  const dobStr = item.json.date_of_birth;
  if (!dobStr) {
    throw new Error('INVALID_DATE_OF_BIRTH: date_of_birth is required');
  }

  const dob = new Date(dobStr);
  if (isNaN(dob.getTime())) {
    throw new Error('INVALID_DATE_OF_BIRTH: Invalid date format: ' + dobStr);
  }

  const today = new Date();
  let age = today.getFullYear() - dob.getFullYear();
  const monthDiff = today.getMonth() - dob.getMonth();

  if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < dob.getDate())) {
    age--;
  }

  if (isNaN(age) || age < 0 || age > 130) {
    throw new Error('INVALID_DATE_OF_BIRTH: Calculated age is out of valid range: ' + age);
  }

  // Determine patient category
  let patientCategory = 'adult';
  if (age < 2) patientCategory = 'infant';
  else if (age < 12) patientCategory = 'child';
  else if (age < 18) patientCategory = 'adolescent';
  else if (age >= 65) patientCategory = 'senior';

  results.push({
    json: {
      ...item.json,
      patient_age: age,
      patient_category: patientCategory
    }
  });
}

return results;

