  const triageOutput = item.json.output || item.json;
  const patientData = $('Calculate Patient Info').first().json;
  const intakeData = $('Extract Patient Data').first().json;

  results.push({
    json: {
      success: true,
      intake_id: intakeData.intake_id,
      patient: {
        name: patientData.patient_name,
        email: patientData.patient_email,
        phone: patientData.patient_phone,
        date_of_birth: patientData.date_of_birth,
        age: patientData.patient_age,
        category: patientData.patient_category,
