// Construct complete normalized Supabase record from AI triage + Patient intake
const aiItem = $input.first().json;
let triage = aiItem.output || aiItem.triage || aiItem;
if (typeof triage === 'string') {
  try { triage = JSON.parse(triage); } catch(e) { triage = {}; }
}

let patient = {};
try {
  patient = $('Calculate Patient Info').first().json || {};
} catch(e) {
  try {
    patient = $('Extract Patient Data').first().json || {};
  } catch(e2) {
    patient = aiItem.patient || {};
  }
}

function ensureArray(val) {
  if (Array.isArray(val)) return val;
  if (!val) return [];
  if (typeof val === 'string') {
    try {
      const parsed = JSON.parse(val);
      if (Array.isArray(parsed)) return parsed;
    } catch(e) {}
    return [val];
  }
  return [val];
}

function ensureInt(val, fallback) {
  const n = parseInt(val, 10);
  return isNaN(n) ? (fallback || 0) : n;
}

const submissionId = String(patient.submission_id || patient.submissionID || ('SUB-' + Date.now()));
const intakeId = patient.intake_id || ('MED-' + submissionId);

const record = {
  intake_id: intakeId,
  submission_id: submissionId,
  patient_name: patient.patient_name || 'Anonymous Patient',
  patient_email: patient.patient_email || 'patient@example.com',
  patient_phone: patient.patient_phone || 'N/A',
  date_of_birth: patient.date_of_birth || '1990-01-01',
  patient_age: ensureInt(patient.patient_age, 35),
  patient_category: patient.patient_category || 'Adult (18-64)',
  reason_for_visit: patient.reason_for_visit || 'Medical consultation',
  symptoms: patient.symptoms || 'No symptoms provided',
  symptom_duration: patient.symptom_duration || 'Not specified',
  pain_level: ensureInt(patient.pain_level, 0),
  current_medications: patient.current_medications || 'None',
  allergies: patient.allergies || 'None',
  medical_history: patient.medical_history || 'None',
  insurance_provider: patient.insurance_provider || 'Self-pay',
  preferred_date: patient.preferred_date || new Date().toISOString().split('T')[0],
  preferred_time: patient.preferred_time || '10:00',
  submission_date: patient.submission_date || new Date().toISOString(),

  // AI Triage Assessment
  urgency_level: (triage.urgency_level || 'routine').toLowerCase().trim(),
  urgency_reasoning: triage.urgency_reasoning || 'AI triage assessment completed.',
  priority_score: ensureInt(triage.priority_score, 30),
  symptom_summary: triage.symptom_summary || patient.symptoms || '',
  red_flag_symptoms: ensureArray(triage.red_flag_symptoms),
  possible_conditions: ensureArray(triage.possible_conditions),
  critical_alerts: ensureArray(triage.critical_alerts),
  recommended_provider: triage.recommended_provider || 'Attending Physician',
  recommended_specialty: triage.recommended_specialty || 'General Medicine',
  questions_for_provider: ensureArray(triage.questions_for_provider),
  exams_needed: ensureArray(triage.exams_needed),
  tests_to_consider: ensureArray(triage.tests_to_consider),
  patient_instructions: ensureArray(triage.patient_instructions),
  items_to_bring: ensureArray(triage.items_to_bring),
  appointment_duration: triage.appointment_duration || '30 minutes',
  detailed_analysis_markdown: triage.detailed_analysis_markdown || ''
};

return [{ json: record }];
